{
  "mode": "compile",
  "question": null,
  "asks_about": "tolerance",
  "unresolved": [],
  "understanding": "The job is to inspect both tyres for cracks or split sidewalls and pump them up to the maximum pressure printed on their sidewalls before a ride. This is a critical safety check to prevent tyre failure at speed in city traffic, verified by photographing the pressure gauge alongside the tyre sidewall.",
  "draft": {
    "key": "pre-ride-tyre-check",
    "title": "Pre-Ride Tyre Inspection and Inflation",
    "strictness": 2,
    "minimum_tier": "attested",
    "disqualifiers": [
      "Cracked tyre",
      "Split sidewall"
    ],
    "releases": [
      "Clearance to ride"
    ],
    "steps": [
      {
        "title": "Secure the Bike",
        "explanation": "The bike must be stable on its stand before starting so it does not fall over while you are working on the wheels.",
        "max_add_fields": 2,
        "fields": [
          {
            "key": "bike_secured",
            "kind": "choice",
            "prompt": "Is the bike stable on its stand?",
            "source": "human",
            "required_at_strictness": 2,
            "choices": [
              "Yes",
              "No"
            ],
            "acceptance_rule": "matches",
            "acceptance_target": "Yes",
            "guidance": "Ensure the stand is fully deployed on flat ground and the bike cannot tip over."
          }
        ]
      },
      {
        "title": "Inspect Tyres for Damage",
        "explanation": "Cracked or split tyres can fail catastrophically at speed, putting the rider in extreme danger.",
        "max_add_fields": 2,
        "fields": [
          {
            "key": "tyre_damage_check",
            "kind": "choice",
            "prompt": "Are both tyres free of cracks and split sidewalls?",
            "source": "human",
            "required_at_strictness": 2,
            "choices": [
              "Yes",
              "No"
            ],
            "acceptance_rule": "matches",
            "acceptance_target": "Yes",
            "guidance": "Inspect the tread and sidewalls of both tyres closely. If you find cracks or splits, do not ride."
          }
        ]
      },
      {
        "title": "Inflate and Verify Front Tyre",
        "explanation": "Pumping the tyre to the maximum pressure printed on the sidewall ensures optimal performance and prevents pinch flats.",
        "max_add_fields": 2,
        "fields": [
          {
            "key": "front_tyre_verification",
            "kind": "photo",
            "prompt": "Take a photo showing the pump gauge reading and the maximum pressure printed on the front tyre sidewall.",
            "source": "camera",
            "required_at_strictness": 2,
            "acceptance_rule": "must_show",
            "guidance": "The photo must clearly show both the pressure gauge needle or digital reading and the max PSI text on the tyre sidewall."
          }
        ]
      },
      {
        "title": "Inflate and Verify Rear Tyre",
        "explanation": "Pumping the tyre to the maximum pressure printed on the sidewall ensures optimal performance and prevents pinch flats.",
        "max_add_fields": 2,
        "fields": [
          {
            "key": "rear_tyre_verification",
            "kind": "photo",
            "prompt": "Take a photo showing the pump gauge reading and the maximum pressure printed on the rear tyre sidewall.",
            "source": "camera",
            "required_at_strictness": 2,
            "acceptance_rule": "must_show",
            "guidance": "The photo must clearly show both the pressure gauge needle or digital reading and the max PSI text on the tyre sidewall."
          }
        ]
      }
    ]
  }
}
